  // Sum integers below limit that are multiples of any factor.
}

solution_code:
function sumMultiples(limit, factors) {
  let sum = 0;
  for (let n = 1; n < limit; n++) {
    if (factors.some((f) => n % f === 0)) sum += n;
  }
  return sum;
}

