function validateUsername(name) {
  if (typeof name !== 'string' || name.trim() === '') return 'Required';
  if (name.length < 3) return 'Too short';
  if (name.length > 16) return 'Too long';
  if (!/^[A-Za-z0-9_]+$/.test(name)) return 'Invalid characters';
  if (!/^[A-Za-z]/.test(name)) return 'Must start with a letter';
  return null;
}

