function capitalize(word) {
  if (!word) return '';
  return word[0].toUpperCase() + word.slice(1);
}

function exclaim(text) {
  return `${text}!`;
}

function greet(name) {
  return exclaim(`Hello, ${capitalize(name)}`);
}

function compose(f, g) {
  return (x) => f(g(x));
}

