solution_code:
function createAccount(owner, opening = 0) {
  let balance = opening;
  const account = {
    get balance() {
      return balance;
    },
    deposit: (amount) => {
      if (!(amount > 0)) throw new RangeError('Deposit must be positive');
      balance += amount;
      return balance;
    },
    withdraw: (amount) => {
      if (!(amount > 0)) throw new RangeError('Withdrawal must be positive');
      if (amount > balance) throw new RangeError('Insufficient funds');
      balance -= amount;
      return balance;
    },
    statement: () => `${owner}: ${balance}`,
  };
  return account;
}

