solution_code:
function processQueue(initial, operations) {
  const queue = [...initial];
  const removed = [];
  for (const [op, item] of operations) {
    if (op === 'enqueue') {
      queue.push(item);
    } else if (op === 'dequeue') {
      if (queue.length > 0) removed.push(queue.shift());
    } else if (op === 'remove') {
      const index = queue.indexOf(item);
      if (index !== -1) removed.push(...queue.splice(index, 1));
    }
  }
  return { queue, removed };
}

