}

solution_code:
function summarize(items) {
  const round2 = (n) => Math.round(n * 100) / 100;
  const kept = items.filter((item) => item.qty > 0);
  const subtotal = kept.reduce((sum, item) => sum + item.price * item.qty, 0);
  const taxableSubtotal = kept.filter((item) => item.taxable).reduce((sum, item) => sum + item.price * item.qty, 0);
  const tax = round2(taxableSubtotal * 0.18);
  return {
    count: kept.length,
    subtotal: round2(subtotal),
    tax,
    total: round2(round2(subtotal) + tax),
    names: kept.map((item) => item.name),
  };
}

