solution_code:
function titleCase(text) {
  const trimmed = text.trim();
  if (!trimmed) return '';
  return trimmed
    .split(/\s+/)
    .map((word) => word[0].toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
}
